/**
 * Contains functions for communicating with a remote server and handling messages received via WebSocket.
 */
import {log_info, log_error} from "../services/Logger";
import { SocketInterface, OnMessageCallback, ConnectionStatusCallback, ConnectionStatus } from "./SocketInterface";

const INTERNAL_RETRY_CODE = 898552

/**
 * A singleton class that acts as an Adaptor for a WebSocket that
 * communicates with a remote server.
 */
export class SocketAdaptor implements SocketInterface {
  /** The single instance of SocketAdaptor */
  private static _instance?: SocketAdaptor;
  /** The function that creates and returns a WebSocket */
  private static socketBuilder: (() => WebSocket) | undefined;
  /** The WebSocket instance being managed */
  private socket?: WebSocket = undefined;
  /** The flag indicating whether the WebSocket connection is open */
  private open: boolean = false;
  /** The flag indicating whether WebSocket message listeners have been added */
  private listening: boolean = false;
  /** The callback that executes when a message is received from the server */
  private readonly onMessage?: OnMessageCallback = undefined;
  /** The callback that executes when connection status changes */
  private readonly onConnectionStatusChange?: ConnectionStatusCallback = undefined;
  /** The ID of the reconnect timeout */
  private static reconnectId: ReturnType<typeof setTimeout> | null = null;
  /** Heartbeat interval */
  private heartbeatInterval: ReturnType<typeof setInterval> | null = null;
  private readonly HEARTBEAT_INTERVAL = 30000; // 30 seconds

  // Pong tracking for detecting dead connections
  private lastPingTime: number = 0;
  private lastPongTime: number = 0;
  private readonly PONG_TIMEOUT = 10000; // 10 seconds

  // Exponential backoff for reconnection
  private reconnectAttempts: number = 0;
  private readonly BASE_RECONNECT_INTERVAL = 1000; // Start at 1s
  private readonly MAX_RECONNECT_INTERVAL = 30000; // Max 30s

  /**
   * Constructs a new instance of SocketAdaptor.
   * @param socketBuilder - A function that creates and returns a WebSocket.
   * @param onMessage - A callback that executes when a message is received from the server.
   * @param onConnectionStatusChange - A callback that executes when connection status changes.
   */
  constructor(
    socketBuilder: () => WebSocket,
    onMessage: OnMessageCallback,
    onConnectionStatusChange?: ConnectionStatusCallback
  ) {
    // Ensure only one instance exists.
    if (SocketAdaptor._instance) {
      return SocketAdaptor._instance;
    }
    SocketAdaptor._instance = this;

    // Initialize properties.
    SocketAdaptor.socketBuilder = socketBuilder;
    this.onMessage = onMessage;
    this.onConnectionStatusChange = onConnectionStatusChange;
    this.socket = socketBuilder();
    this.addListeners();
    // Note: heartbeat is started in onopen handler after successful connection
  }

  /**
   * Calculates reconnect delay with exponential backoff and jitter.
   */
  private getReconnectDelay = (): number => {
    const delay = Math.min(
      this.BASE_RECONNECT_INTERVAL * Math.pow(2, this.reconnectAttempts),
      this.MAX_RECONNECT_INTERVAL
    );
    // Add 0-500ms jitter to prevent thundering herd
    return delay + Math.random() * 500;
  }

  /**
   * Notifies listeners of connection status changes.
   */
  private notifyConnectionStatus = (status: ConnectionStatus) => {
    if (this.onConnectionStatusChange) {
      this.onConnectionStatusChange(status, this.reconnectAttempts);
    }
  }

  static CloseAll = () => {
    if (SocketAdaptor._instance) {
      SocketAdaptor._instance.close();
      SocketAdaptor._instance = undefined;
    }
  }

  /**
   * Adds listeners for WebSocket open and message events.
   */
  addListeners = () => {
    if (typeof this.socket !== "undefined" && !this.listening) {
      this.listening = true;
      const self = this;

      // Sends a message when the WebSocket is opened.
      this.socket.onopen = () => {
        console.log("open websocket event");
        if (typeof self.socket !== "undefined") {
          self.open = true;
          // Reset reconnection state on successful connection
          self.reconnectAttempts = 0;
          self.lastPingTime = 0;
          self.lastPongTime = 0;
          // Start heartbeat now that connection is open
          self.startHeartbeat();
          self.notifyConnectionStatus('connected');
          self.send({SendLastState: null});
        }
      };

      this.socket.onerror = (error) => {
        console.log(`WebSocket encountered error: ${JSON.stringify(error)}, closing socket`);
        self.retryReconnect();
      };

      this.socket.onclose = (event) => {
        if (event.code !== INTERNAL_RETRY_CODE) {
          console.log(`WebSocket closed code: ${event.code}, reason: ${event.reason} reconnecting...`);
          self.open = false;
          self.retryReconnect();
        }
      };

      // Parses a message when one is received.
      this.socket.onmessage = (event) => {
        self.onReceive(event).catch(err => log_info(`onReceive exception: ${err}`));
      }
    }
  }

  retryReconnect = () => {
    if (SocketAdaptor.reconnectId === null) {
      const delay = this.getReconnectDelay();
      console.log(`Scheduling reconnect attempt ${this.reconnectAttempts + 1} in ${Math.round(delay)}ms`);
      this.notifyConnectionStatus('reconnecting');
      SocketAdaptor.reconnectId = setTimeout(this._reconnect, delay);
    }
  }

  startHeartbeat = () => {
    // Stop any existing heartbeat first to prevent duplicates
    this.stopHeartbeat();
    this.heartbeatInterval = setInterval(() => {
      this.checkConnection();
    }, this.HEARTBEAT_INTERVAL);
  }

  stopHeartbeat = () => {
    if (this.heartbeatInterval) {
      clearInterval(this.heartbeatInterval);
      this.heartbeatInterval = null;
    }
  }

  checkConnection = () => {
    // If a reconnect is already scheduled, don't spam checks
    if (SocketAdaptor.reconnectId !== null) {
      return;
    }

    // Check if we're waiting too long for a pong response
    if (this.lastPingTime > 0 && this.lastPongTime < this.lastPingTime) {
      const elapsed = Date.now() - this.lastPingTime;
      if (elapsed > this.PONG_TIMEOUT) {
        console.log(`No pong received in ${elapsed}ms, connection appears dead. Reconnecting...`);
        this.retryReconnect();
        return;
      }
    }

    if (!this.isReady()) {
      console.log("Connection is not ready, attempting to reconnect...");
      this.retryReconnect();
    } else {
      this.lastPingTime = Date.now();
      this.send({ Ping: this.lastPingTime });
    }
  }

  /**
   * Closes the WebSocket connection.
   * @param code - A numeric value representing the code for closing the connection.
   * @param reason - A reason for closing the connection.
   */
  close = (code?: number  , reason?: string  ) => {
    this.stopHeartbeat();
    if (typeof this.socket !== "undefined") {
      try {
        this.socket.onclose = null;
        this.socket.onerror = null;
        this.socket.onmessage = null;
        this.socket.onopen = null;
        this.socket.close(code, reason);
      } catch {
        // ignore any errors from attempting to close the socket.
      }

      this.socket = undefined;
      this.open = false;
      this.listening = false;
    }
  }

  /**
   * Sends a string to the remote server.
   * @param message - The message to send.
   */
  send_string = (message: string) => {
    if (typeof this.socket !== "undefined" && this.open) {
      this.socket.send(message);
    }
  }

  /**
   * Sends a message to the remote server.
   * @param message - The message to send.
   */
  send = <T,>(message: T) => {
    if (typeof this.socket !== "undefined" && this.open && SocketAdaptor.reconnectId === null) {
      // Serialize the object as a JSON string
      const jsonString = JSON.stringify(message);

      // Convert the JSON string to a Blob
      const blob = new Blob([jsonString], { type: "application/json" });

      if (this.socket.readyState > 1) {
        this._reconnect();
      }

      for (let attempts = 0; attempts < 3; attempts++) {
        try {
          this.socket.send(blob);
          break;
        } catch (error) {
          this._reconnect();
        }
      }
    }
  }

  /**
   * Parses a message received from the server.
   * @param event - The event containing the message.
   */
  onReceive = async (event: any) => {
    if (typeof this.socket !== "undefined" && this.open && typeof this.onMessage !== "undefined") {
      if (typeof event.data === "string") {
        // Log message.
        log_info(event.data);
      } else {
        // Parse received message.
        await this._parseMessage(event);
      }
    }
  }

  /**
   * Parses a message received from the server.
   * @param event - The event to parse.
   */
  _parseMessage = async (event: any)=> {
    try {
      // Convert response to text.
      const txt = await new Response(event.data).text();
      // Parse JSON data.
      const data = JSON.parse(txt);

      // Handle Pong messages to update connection health tracking
      if (data.Pong !== undefined) {
        this.lastPongTime = Date.now();
        // Don't pass Pong to application layer, it's internal
        return;
      }

      // Execute callback with parsed data.
      this.onMessage!(data);
    } catch (error) {
      // Log and throw error.
      log_error(`error ${error}, received unexpected message: ${event.data}`);
      //throw error;
    }
  }

  /**
   * Returns true if the WebSocket is open and ready for communication.
   * @return - A boolean indicating if the WebSocket is open.
   */
  isReady = ():boolean => {
    return (typeof this.socket !== "undefined" && this.open);
  }

  _reconnect = () => {
    if (SocketAdaptor.socketBuilder) {
      try {
        // Avoid reconnecting when socket is already connecting/open
        if (this.socket && (this.socket.readyState === WebSocket.CONNECTING || this.socket.readyState === WebSocket.OPEN)) {
          if (SocketAdaptor.reconnectId !== null) {
            clearTimeout(SocketAdaptor.reconnectId);
            SocketAdaptor.reconnectId = null;
          }
          return;
        }

        // Increment attempt counter before trying
        this.reconnectAttempts++;
        console.log(`Reconnection attempt ${this.reconnectAttempts}...`);

        // Close existing socket (this also stops heartbeat)
        this.close(INTERNAL_RETRY_CODE);

        // Create new socket and add listeners
        this.socket = SocketAdaptor.socketBuilder();
        this.addListeners();
        // Note: heartbeat is started in onopen handler after successful connection

        // Clear the reconnect timeout
        if (SocketAdaptor.reconnectId !== null) {
          clearTimeout(SocketAdaptor.reconnectId);
          SocketAdaptor.reconnectId = null;
        }
      } catch (error) {
        console.log(`Error reconnecting WebSocket: ${error}`);
        this.retryReconnect(); // Attempt to reconnect again
      }
    } else {
      console.log("Cannot reconnect to WebSocket: no socketBuilder");
    }
  }
}